def encode_genotypes(df):
    """Site tokens to a 0/1 matrix, germline as 0 and mature as 1."""
    token_map = {germline_token: 0, mutant_token: 1}
    try:
        return np.vectorize(token_map.__getitem__)(df[site_cols].to_numpy()).astype(float)
    except KeyError as exc:
        raise ValueError(f"unexpected site token {exc}, expected only G and M")


def apply_censoring(y):
    """Censor indicator (-1 left, 0 observed, 1 right) with the response clamped to the threshold."""
    y = np.asarray(y, float).copy()
    cens = np.zeros(len(y))
    if left_censor > -1:
        cens[y <= left_censor] = -1
        y[cens == -1] = left_censor
    if right_censor > -1:
        cens[y >= right_censor] = 1
        y[cens == 1] = right_censor
    return y, cens


def prepare(df, antigen):
    """One antigen's rows as design-ready arrays plus the labels that define LOGO folds."""
    sub = df.loc[df[antigen_col] == antigen].reset_index(drop=True)
    if sub.empty:
        raise ValueError(f"no rows for antigen {antigen}")
    genotypes = encode_genotypes(sub)
    y, cens = apply_censoring(sub[kd_column].to_numpy(float))
    return genotypes, y, cens, sub[genotype_id_column].tolist()

def resolve_reg_type(alpha_l1, alpha_l2):
    """Which regime a grid cell lands in, so the alpha = 0 edges are not mislabeled elastic."""
    if alpha_l1 > 0 and alpha_l2 > 0:
        return "elastic_net"
    if alpha_l1 > 0:
        return "l1"
    if alpha_l2 > 0:
        return "l2"
    return "none"


def logo_cv(df, antigen, order, alpha_l1=0.0, alpha_l2=0.0, max_folds=None,
            skip_failed_folds=False, verbose=False):
    """Summed held-out Tobit NLL over leave-one-genotype-out folds for one condition."""
    genotypes, y, cens, labels = prepare(df, antigen)
    poly, keep, _, _ = build_design(genotypes, order)
    x = poly.transform(genotypes)[:, keep]
    scale = max(1, len(keep) - 1)

    unique = list(dict.fromkeys(labels))
    n_folds = len(unique) if max_folds is None else min(max_folds, len(unique))
    label_arr = np.array(labels, dtype=object)

    fold_nlls, n_failed, first_error = [], 0, None
    for i in range(n_folds):
        test = label_arr == unique[i]
        try:
            coeffs, sigma, _, _ = fit_tobit(x[~test], y[~test], cens[~test],
                                            alpha_l1 * scale, alpha_l2 * scale)
            value = float(pointwise_nll(x[test], y[test], cens[test], coeffs, sigma).sum())
            if not np.isfinite(value):
                raise ValueError(f"non-finite nll on fold {i}")
            fold_nlls.append(value)
        except Exception as exc:
            n_failed += 1
            if first_error is None:
                first_error = f"fold {i}: {type(exc).__name__}: {exc}"
            if verbose:
                print("fold", i, "failed:", exc)

    if n_failed and not skip_failed_folds:
        cv_nll = float("nan")
    elif not fold_nlls:
        cv_nll = float("nan")
    else:
        cv_nll = float(np.sum(fold_nlls))

    return {"antigen": antigen, "order": order, "alpha_l1": alpha_l1, "alpha_l2": alpha_l2,
            "reg_type": resolve_reg_type(alpha_l1, alpha_l2), "n_folds": n_folds,
            "n_folds_ok": len(fold_nlls), "n_folds_failed": n_failed,
            "cv_nll": cv_nll, "first_error": first_error}


def sweep(df, antigen, out_path=None, max_folds=None, order_list=None):
    """Run the order by penalty grid for one complex, appending each condition as it finishes."""
    rows = []
    for order in (order_list or orders):
        for a1 in alphas_l1:
            for a2 in alphas_l2:
                row = logo_cv(df, antigen, order, a1, a2, max_folds=max_folds)
                rows.append(row)
                if out_path:
                    header = not os.path.exists(out_path) or os.path.getsize(out_path) == 0
                    with open(out_path, "a", newline="") as fh:
                        pd.DataFrame([row]).to_csv(fh, header=header, index=False)
                        fh.flush()
                        os.fsync(fh.fileno())
                print(f"order {order} a1={a1:g} a2={a2:g} cv_nll={row['cv_nll']:.4f}", flush=True)
    return pd.DataFrame(rows)


def select_best(results):
    """Winning condition per antigen: lowest cv_nll among conditions whose folds all completed."""
    tab = pd.DataFrame(results)
    clean = tab[tab["cv_nll"].notna() & (tab["n_folds_failed"] == 0)]
    if clean.empty:
        return tab, clean
    return tab, clean.sort_values("cv_nll").groupby("antigen", as_index=False).first()
